            long sumF = 0;
            long sumG = 0;
            for (int i = 0; i <= t; i++) {
                int j = t - i;
                long ways = C(n, i) * C(n, j) % MOD;
                long sign = ((i + j) & 1) == 0 ? 1 : MOD - 1;
                ways = ways * sign % MOD;

                long invI1 = modPow(i + 1, MOD - 2);
                long invJ1 = modPow(j + 1, MOD - 2);
                long invI2 = modPow(i + 2, MOD - 2);
                long invJ2 = modPow(j + 2, MOD - 2);

                long termF = ways * invI1 % MOD * invJ1 % MOD;
                long termG = ways * invI2 % MOD * invJ2 % MOD;

                sumF = (sumF + termF) % MOD;
                sumG = (sumG + termG) % MOD;
            }
            f[t] = sumF;
            g[t] = sumG;
        }

        long ans = 0;
        for (int t = k; t <= n; t++) {
            long coef = (f[t] - g[t]) % MOD;
            if (coef < 0) coef += MOD;
            ans = (ans + coef) % MOD;
        }

        ans = ans * L % MOD;
        System.out.println(ans);
    }

