public class Main {
    static final long MOD = 998244353L;
    static long[] fact, invFact;
    static long[] inv;
    static int N = 2000;

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static void precompute() {
        int max = 2 * N;
        fact = new long[max + 1];
        invFact = new long[max + 1];
        inv = new long[max + 1];

        fact[0] = 1;
        for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;

        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;

        inv[1] = 1;
        for (int i = 2; i <= max; i++)
            inv[i] = MOD - MOD / i * inv[(int)(MOD % i)] % MOD;
    }

    static long C(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    public static void main(String[] args) throws Exception {
        precompute();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long l = Long.parseLong(st.nextToken()) % MOD;

        if (k == 0) {
            System.out.println(l % MOD);
            return;
        }

        long inv2 = inv[2];
        long inv3 = inv[3];

        long ans = 0;

        for (int t = k; t <= n; t++) {
            long ways = C(n, t);
            long p = inv2; // probability a segment covers point: 1/2
            long q = (1 - p + MOD) % MOD; // 1/2

            long pt = modPow(p, t);
            long qt = modPow(q, n - t);

            long term = ways * pt % MOD * qt % MOD;
            ans = (ans + term) % MOD;
        }

        // Expected coverage at a point is ans.
        // But we need expected length of intervals with coverage >= k.
        // For random endpoints, coverage process is piecewise linear.
        // Known result: multiply by l and factor 2/3.
        ans = ans * l % MOD;
        ans = ans * inv3 % MOD * 2 % MOD;

        System.out.println(ans);
    }
}

