    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) != 0) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int k = fs.nextInt();
        long L = fs.nextLong();

        if (k == 0) {
            System.out.println(L % MOD);
            return;
        }

        int max = 2 * n;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long[] inv = new long[max + 1];
        for (int i = 1; i <= max; i++) inv[i] = modPow(i, MOD - 2);

        long[][] dp = new long[n + 1][n + 1];
        dp[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int c = 0; c <= i; c++) {
                long cur = dp[i][c];
                if (cur == 0) continue;

                int rem = n - i;

                // case 1: segment not covering x (both endpoints on same side)
                long waysSameSide = 2L * c + 1;
                long probSameSide = waysSameSide * inv[rem * 2] % MOD;
                dp[i + 1][c] = (dp[i + 1][c] + cur * probSameSide) % MOD;

                // case 2: segment covering x (one endpoint on each side)
                long waysCross = (long) (rem * 2) - waysSameSide;
                if (waysCross < 0) waysCross += MOD;
                long probCross = waysCross * inv[rem * 2] % MOD;
                dp[i + 1][c + 1] = (dp[i + 1][c + 1] + cur * probCross) % MOD;
            }
        }

        long ansProb = 0;
        for (int c = k; c <= n; c++) {
            ansProb = (ansProb + dp[n][c]) % MOD;
        }

        long ans = ansProb * (L % MOD) % MOD;
        System.out.println(ans);
    }

    // Fast scanner
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
